/*

  PORTED FROM
  https://ddzeb.com/lands#clip-91



  tested the following code with two machines
  and got different results.

  machine 1: macOS Big Sur, Intel Graphics Card
  machine 2: macOS Sequoia, Apple M1

  check out this blog post:
  https://ddzeb.com/blog/post#72/glsl-inconsistent-behavior


*/

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
  float x = (fragCoord.x * 2.0 - iResolution.x) / iResolution.x;
  x = floor(x * 10.);
  x = fract(cos(x) * 43758.);
  fragColor = vec4(x, 0, 0, 1.0);
}
